package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.regex.Pattern;
import java.util.regex.PatternSyntaxException;
import org.jsoup.Jsoup;
import org.jsoup.helper.StringUtil;
import org.jsoup.helper.Validate;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;
import org.jsoup.nodes.TextNode;
import org.jsoup.parser.Parser;
import org.jsoup.parser.Tag;
import org.jsoup.select.Collector;
import org.jsoup.select.Elements;
import org.jsoup.select.Evaluator;
import org.jsoup.select.Selector;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class Element_clone_TriageGen0Test {

    private Element originalElement;
    private Element clonedElement;

    @Before
    public void setUp() {
        // Create a sample Element with some attributes and children
        originalElement = new Element(Tag.valueOf("div"), "", new org.jsoup.nodes.Attributes.Builder()
                .add("id", "test")
                .add("class", "container")
                .build());
        originalElement.appendChild(new TextNode("Hello, World!", 0, 13, originalElement));
        originalElement.appendChild(new Element(Tag.valueOf("span"), "", new org.jsoup.nodes.Attributes.Builder()
                .add("class", "highlight")
                .build()).appendText("Sample Text"));
    }

    @Test
    public void testCloneElement() {
        // Test cloning the element
        clonedElement = originalElement.clone();

        // Check if the clone is not the same instance
        assertNotSame(originalElement, clonedElement);

        // Check if the clone has the same tag name
        assertEquals(originalElement.tagName(), clonedElement.tagName());

        // Check if the clone has the same attributes
        assertEquals(originalElement.attributes(), clonedElement.attributes());

        // Check if the clone has the same children count
        assertEquals(originalElement.children().size(), clonedElement.children().size());

        // Check if the clone's children are not the same instances
        for (int i = 0; i < originalElement.children().size(); i++) {
            assertNotSame(originalElement.child(i), clonedElement.child(i));
        }

        // Check if the clone's children have the same content
        for (int i = 0; i < originalElement.children().size(); i++) {
            assertEquals(originalElement.child(i).ownText(), clonedElement.child(i).ownText());
        }
    }

    @Test
    public void testCloneElementWithNoAttributes() {
        // Create an element with no attributes
        Element noAttrElement = new Element(Tag.valueOf("p"), "");
        noAttrElement.appendChild(new TextNode("No attributes", 0, 15, noAttrElement));

        // Clone the element
        Element clonedNoAttrElement = noAttrElement.clone();

        // Check if the clone is not the same instance
        assertNotSame(noAttrElement, clonedNoAttrElement);

        // Check if the clone has no attributes
        assertTrue(clonedNoAttrElement.attributes().isEmpty());

        // Check if the clone has the same text
        assertEquals(noAttrElement.ownText(), clonedNoAttrElement.ownText());
    }

    @Test
    public void testCloneElementWithNestedChildren() {
        // Create an element with nested children
        Element nestedElement = new Element(Tag.valueOf("div"), "", new org.jsoup.nodes.Attributes.Builder()
                .add("id", "nested")
                .build());
        Element child1 = new Element(Tag.valueOf("span"), "", new org.jsoup.nodes.Attributes.Builder()
                .add("class", "inner")
                .build()).appendText("Nested Child 1");
        Element child2 = new Element(Tag.valueOf("span"), "", new org.jsoup.nodes.Attributes.Builder()
                .add("class", "inner")
                .build()).appendText("Nested Child 2");
        nestedElement.appendChild(child1);
        nestedElement.appendChild(child2);

        // Clone the element
        Element clonedNestedElement = nestedElement.clone();

        // Check if the clone is not the same instance
        assertNotSame(nestedElement, clonedNestedElement);

        // Check if the clone has the same tag name
        assertEquals(nestedElement.tagName(), clonedNestedElement.tagName());

        // Check if the clone has the same attributes
        assertEquals(nestedElement.attributes(), clonedNestedElement.attributes());

        // Check if the clone has the same children count
        assertEquals(nestedElement.children().size(), clonedNestedElement.children().size());

        // Check if the clone's children are not the same instances
        for (int i = 0; i < nestedElement.children().size(); i++) {
            assertNotSame(nestedElement.child(i), clonedNestedElement.child(i));
        }

        // Check if the clone's children have the same content
        for (int i = 0; i < nestedElement.children().size(); i++) {
            assertEquals(nestedElement.child(i).ownText(), clonedNestedElement.child(i).ownText());
        }
    }

    @Test(expected = CloneNotSupportedException.class)
    public void testCloneElementThrowsException() {
        // Create an element with a non-clonable tag
        Element nonClonableElement = new Element(Tag.valueOf("unsupported"), "", new org.jsoup.nodes.Attributes.Builder()
                .add("id", "non-clonable")
                .build());

        // Attempt to clone the element
        nonClonableElement.clone();
    }
}
